<script lang="ts">
  import { onMount } from "svelte";
  import { createProduct, getDashboardSummary, listMovements, listProducts, recordMovement } from "$lib/api";
  import type { DashboardSummary, Movement, Product } from "$lib/types";
  import "$lib/../app.css";

  type View = "Dashboard" | "Products" | "Stock" | "Transactions";
  const navItems: { label: View; icon: string }[] = [
    { label: "Dashboard", icon: "⌂" }, { label: "Products", icon: "□" }, { label: "Stock", icon: "↕" }, { label: "Transactions", icon: "≡" },
  ];

  let activeView: View = $state("Dashboard");
  let products: Product[] = $state([]);
  let movements: Movement[] = $state([]);
  let summary: DashboardSummary = $state({ activeProducts: 0, totalUnits: 0, lowStock: 0, recentMovements: [] });
  let search = $state("");
  let showProductForm = $state(false);
  let showMovementForm = $state(false);
  let movementType = $state<"purchase" | "sale" | "adjustment">("purchase");
  let name = $state("");
  let unit = $state("pieces");
  let openingQuantity = $state(0);
  let selectedProductId = $state(0);
  let quantity = $state(1);
  let note = $state("");
  let isSaving = $state(false);
  let error = $state("");

  let filteredProducts = $derived(products.filter((product) =>
    `${product.name} ${product.productCode}`.toLowerCase().includes(search.toLowerCase()),
  ));

  onMount(async () => { await refresh(); });
  async function refresh() {
    [products, movements, summary] = await Promise.all([listProducts(), listMovements(), getDashboardSummary()]);
  }
  async function saveProduct(event: SubmitEvent) {
    event.preventDefault(); error = ""; isSaving = true;
    try { await createProduct(name, unit, openingQuantity); showProductForm = false; name = ""; openingQuantity = 0; await refresh(); }
    catch (caught) { error = String(caught); } finally { isSaving = false; }
  }
  async function saveMovement(event: SubmitEvent) {
    event.preventDefault(); error = ""; isSaving = true;
    try {
      await recordMovement(`record_${movementType}`, selectedProductId, quantity, note);
      showMovementForm = false; note = ""; await refresh();
    } catch (caught) { error = String(caught); } finally { isSaving = false; }
  }
  function openMovement(type: typeof movementType) {
    movementType = type; selectedProductId = products[0]?.id ?? 0; quantity = 1; showMovementForm = true;
  }
  function formatDate(value: string) { return new Intl.DateTimeFormat("en", { month: "short", day: "numeric", year: "numeric" }).format(new Date(value)); }
  function movementLabel(type: string) { return type === "purchase" ? "Purchase" : type === "sale" ? "Sale" : type === "opening" ? "Opening stock" : "Adjustment"; }
</script>

<svelte:head><title>StockLite · Inventory workspace</title></svelte:head>

<div class="app-shell">
  <aside class="sidebar">
    <div class="brand"><div class="brand-mark">S</div><div><strong>StockLite</strong><span>Inventory workspace</span></div></div>
    <nav>
      <p class="nav-heading">WORKSPACE</p>
      {#each navItems as item}<button class:active={activeView === item.label} onclick={() => activeView = item.label}><span class="nav-icon">{item.icon}</span>{item.label}</button>{/each}
    </nav>
    <div class="sidebar-bottom"><div class="offline"><span></span><div><strong>Offline mode</strong><small>Data stays on this device</small></div></div><button class="settings">⚙ <span>Settings</span></button><div class="profile"><div class="avatar">JD</div><div><strong>Jamie Davis</strong><small>Administrator</small></div><span>⋯</span></div></div>
  </aside>

  <main class="content">
    <header class="topbar"><div class="crumb">Workspace <span>/</span> <b>{activeView}</b></div><div class="top-actions"><span class="today">Today, {new Intl.DateTimeFormat("en", { month: "short", day: "numeric", year: "numeric" }).format(new Date())}</span><button class="icon-button">?</button><button class="icon-button notification">♧<i></i></button></div></header>
    <section class="page">
      {#if activeView === "Dashboard"}
        <div class="page-heading"><div><p class="eyebrow">OVERVIEW</p><h1>Good morning, Jamie <span>✦</span></h1><p class="subtitle">Here’s what’s happening with your inventory today.</p></div><button class="primary" onclick={() => showProductForm = true}>＋ Add product</button></div>
        <div class="stats"><div class="stat-card"><div class="stat-icon green">▣</div><div><span>Active products</span><strong>{summary.activeProducts}</strong><small class="positive">↑ 8.2% <em>vs last month</em></small></div></div><div class="stat-card"><div class="stat-icon blue">◫</div><div><span>Total stock units</span><strong>{summary.totalUnits.toLocaleString()}</strong><small class="muted">Across all products</small></div></div><div class="stat-card"><div class="stat-icon amber">⌁</div><div><span>Low stock alerts</span><strong>{summary.lowStock}</strong><small class="warning">Needs attention</small></div></div></div>
        <div class="dashboard-grid"><section class="panel recent"><div class="panel-header"><div><h2>Recent activity</h2><p>Your latest inventory movements</p></div><button class="text-button" onclick={() => activeView = "Transactions"}>View all <span>→</span></button></div>{#each summary.recentMovements as movement}<div class="activity-row"><div class="activity-icon {movement.movementType}">{movement.movementType === "sale" ? "↗" : movement.movementType === "purchase" ? "↙" : "↕"}</div><div class="activity-main"><strong>{movementLabel(movement.movementType)}</strong><span>{movement.productName}</span></div><div class:negative={movement.quantityDelta < 0} class="activity-quantity">{movement.quantityDelta > 0 ? "+" : ""}{movement.quantityDelta}</div><time>{formatDate(movement.occurredAt)}</time></div>{:else}<div class="empty">No activity yet.</div>{/each}</section><section class="panel quick"><div class="panel-header"><div><h2>Quick actions</h2><p>Keep your stock up to date</p></div></div><button onclick={() => openMovement("purchase")}><span class="quick-icon purchase">↙</span><div><strong>Record a purchase</strong><small>Add incoming stock from a supplier</small></div><span>→</span></button><button onclick={() => openMovement("sale")}><span class="quick-icon sale">↗</span><div><strong>Record a sale</strong><small>Remove stock for a customer order</small></div><span>→</span></button><button onclick={() => openMovement("adjustment")}><span class="quick-icon adjustment">↕</span><div><strong>Make an adjustment</strong><small>Correct a stock count discrepancy</small></div><span>→</span></button></section></div>
      {:else if activeView === "Products"}
        <div class="page-heading"><div><p class="eyebrow">CATALOG</p><h1>Products</h1><p class="subtitle">Manage your products and keep an eye on current stock.</p></div><button class="primary" onclick={() => showProductForm = true}>＋ Add product</button></div>
        <section class="panel table-panel"><div class="table-toolbar"><div class="search"><span>⌕</span><input placeholder="Search products..." bind:value={search} /></div><span class="result-count">{filteredProducts.length} products</span></div><table><thead><tr><th>PRODUCT</th><th>PRODUCT ID</th><th>UNIT</th><th>CURRENT STOCK</th><th>STATUS</th><th></th></tr></thead><tbody>{#each filteredProducts as product}<tr><td><strong>{product.name}</strong></td><td class="code">{product.productCode}</td><td>{product.unit}</td><td><strong>{product.currentStock}</strong></td><td><span class="status"><i></i> In stock</span></td><td class="more">⋯</td></tr>{:else}<tr><td colspan="6" class="empty">No products found.</td></tr>{/each}</tbody></table></section>
      {:else if activeView === "Stock"}
        <div class="page-heading"><div><p class="eyebrow">INVENTORY CONTROL</p><h1>Stock movements</h1><p class="subtitle">Record every change so your balance always reconciles.</p></div></div><div class="action-cards"><button onclick={() => openMovement("purchase")}><span class="quick-icon purchase">↙</span><strong>Purchase</strong><small>Receive incoming stock</small></button><button onclick={() => openMovement("sale")}><span class="quick-icon sale">↗</span><strong>Sale</strong><small>Record outgoing stock</small></button><button onclick={() => openMovement("adjustment")}><span class="quick-icon adjustment">↕</span><strong>Adjustment</strong><small>Correct a discrepancy</small></button></div>
      {:else}
        <div class="page-heading"><div><p class="eyebrow">AUDIT TRAIL</p><h1>Transactions</h1><p class="subtitle">A complete, append-only history of your inventory.</p></div></div><section class="panel table-panel"><div class="table-toolbar"><div class="search"><span>⌕</span><input placeholder="Search transactions..." /></div><button class="filter">≡ Filters</button></div><table><thead><tr><th>DATE</th><th>PRODUCT</th><th>TYPE</th><th>QUANTITY CHANGE</th><th>NOTE</th></tr></thead><tbody>{#each movements as movement}<tr><td>{formatDate(movement.occurredAt)}</td><td><strong>{movement.productName}</strong></td><td><span class="type-pill {movement.movementType}">{movementLabel(movement.movementType)}</span></td><td class:negative={movement.quantityDelta < 0} class="delta">{movement.quantityDelta > 0 ? "+" : ""}{movement.quantityDelta}</td><td class="muted">{movement.note ?? "—"}</td></tr>{:else}<tr><td colspan="5" class="empty">No transactions yet.</td></tr>{/each}</tbody></table></section>
      {/if}

      <style>
        .app-shell{display:flex;min-height:100vh;background:#f7faf8}.sidebar{width:248px;background:#fff;border-right:1px solid #e7eee9;padding:28px 16px 18px;display:flex;flex-direction:column}.brand{display:flex;align-items:center;gap:11px;padding:0 12px 42px}.brand-mark{background:#2d8060;color:#fff;width:32px;height:32px;border-radius:10px;display:grid;place-items:center;font:800 18px Manrope}.brand strong{display:block;font:800 17px Manrope;letter-spacing:-.4px}.brand span{display:block;color:#91a097;font-size:10px;margin-top:1px}.nav-heading,.eyebrow{color:#8fa097;font-size:10px;font-weight:700;letter-spacing:1.4px}.nav-heading{padding:0 13px;margin:0 0 12px}.sidebar nav button{border:0;background:transparent;color:#7e8e84;width:100%;padding:11px 13px;border-radius:9px;text-align:left;font-size:13px;margin:2px 0}.sidebar nav button.active{background:#eaf6ef;color:#267653;font-weight:700}.nav-icon{display:inline-block;width:26px;font-size:17px}.sidebar-bottom{margin-top:auto}.offline{display:flex;gap:10px;background:#f7faf8;padding:12px;border-radius:9px;margin:0 4px 18px}.offline>span{background:#44a675;border:3px solid #d9f2e3;border-radius:50%;height:10px;width:10px;margin-top:3px}.offline strong,.offline small,.profile strong,.profile small{display:block}.offline strong{font-size:11px}.offline small,.profile small{color:#99a59e;font-size:10px;margin-top:2px}.settings{color:#87958d;width:100%;border:0;background:transparent;text-align:left;padding:11px 13px;font-size:12px;margin-bottom:14px}.profile{border-top:1px solid #edf1ee;padding:16px 4px 0;display:flex;align-items:center;gap:9px}.profile>span{margin-left:auto;color:#abb6af}.avatar{width:30px;height:30px;border-radius:50%;background:#e6e1d7;color:#836f4d;display:grid;place-items:center;font-size:10px;font-weight:700}.content{flex:1}.topbar{height:68px;border-bottom:1px solid #e7eee9;background:#fff;display:flex;align-items:center;justify-content:space-between;padding:0 42px}.crumb{color:#9daaa3;font-size:12px}.crumb span{margin:0 9px;color:#d1d9d4}.crumb b{color:#425248;font-weight:600}.top-actions{display:flex;align-items:center;gap:18px}.today{font-size:11px;color:#89978f}.icon-button{border:0;background:transparent;color:#819087;font-size:16px}.notification{position:relative}.notification i{position:absolute;width:5px;height:5px;background:#e98f76;border:1px solid #fff;border-radius:50%;top:0;right:0}.page{padding:36px 42px 60px;max-width:1400px}.page-heading{display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:31px}.eyebrow{margin:0 0 8px}.page-heading h1{font:800 28px Manrope;margin:0;letter-spacing:-1.1px}.page-heading h1 span{font-size:19px;color:#d1a96c;vertical-align:5px;margin-left:4px}.subtitle,.modal-subtitle{font-size:12px;color:#9aa69f;margin:8px 0 0}.primary{border:0;background:#2d8060;color:white;border-radius:7px;padding:11px 16px;font-size:12px;font-weight:700;box-shadow:0 3px 8px #2d806021}.primary:hover{background:#246b50}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-bottom:24px}.stat-card{background:#fff;border:1px solid #e9efeb;border-radius:10px;padding:20px;display:flex;gap:14px;align-items:flex-start;box-shadow:0 3px 14px #153b2410}.stat-card span{display:block;color:#88968e;font-size:11px;margin-bottom:7px}.stat-card strong{display:block;font:800 25px Manrope;letter-spacing:-1px}.stat-card small{font-size:10px;display:block;margin-top:7px}.positive{color:#40a473}.positive em{color:#a2ada6;font-style:normal;margin-left:4px}.muted{color:#9ba7a0!important}.warning{color:#d08d53}.stat-icon{width:35px;height:35px;border-radius:9px;display:grid;place-items:center;font-size:17px}.stat-icon.green{background:#e5f5eb;color:#328a63}.stat-icon.blue{background:#e9f1f8;color:#5681a6}.stat-icon.amber{background:#fdf1df;color:#c18b4b}.dashboard-grid{display:grid;grid-template-columns:1.35fr 1fr;gap:18px}.panel{background:#fff;border:1px solid #e9efeb;border-radius:10px;box-shadow:0 3px 14px #153b2408}.panel-header{display:flex;align-items:flex-start;justify-content:space-between;padding:22px 22px 14px}.panel h2{font:700 14px Manrope;margin:0}.panel-header p{font-size:11px;color:#a0aba5;margin:5px 0 0}.text-button{border:0;background:transparent;color:#3b8b67;font-size:11px;font-weight:700;margin-top:5px}.text-button span{font-size:16px;margin-left:5px}.activity-row{display:flex;align-items:center;gap:11px;margin:0 22px;padding:14px 0;border-top:1px solid #f0f3f1}.activity-icon,.quick-icon{height:30px;width:30px;border-radius:8px;display:grid;place-items:center;font-size:16px}.activity-icon.purchase,.quick-icon.purchase{background:#e7f4eb;color:#3f9b6b}.activity-icon.sale,.quick-icon.sale{background:#fff0e8;color:#db916d}.activity-icon.adjustment,.quick-icon.adjustment{background:#f0edfa;color:#8a78b8}.activity-main{flex:1}.activity-main strong,.activity-main span{display:block}.activity-main strong{font-size:11px}.activity-main span{font-size:10px;color:#a0aba5;margin-top:3px}.activity-quantity{font-size:12px;font-weight:700;color:#3b956a}.activity-quantity.negative,.delta.negative{color:#d5826a}.activity-row time{font-size:10px;color:#a8b0aa}.quick>button{display:flex;align-items:center;gap:11px;width:calc(100% - 44px);margin:0 22px;padding:14px 0;border:0;border-top:1px solid #f0f3f1;background:transparent;text-align:left}.quick>button>div{flex:1}.quick strong,.quick small{display:block}.quick strong{font-size:11px}.quick small{font-size:10px;color:#a0aba5;margin-top:3px}.quick>button>span:last-child{font-size:16px;color:#9aa9a1}.empty{text-align:center;color:#a2ada6;font-size:12px;padding:34px}.table-panel{overflow:hidden}.table-toolbar{display:flex;align-items:center;gap:15px;padding:16px 20px;border-bottom:1px solid #edf1ee}.search{display:flex;align-items:center;gap:8px;border:1px solid #e4ebe6;border-radius:7px;padding:8px 10px;width:270px;color:#91a097}.search input{border:0;outline:0;color:#425248;font-size:11px;width:100%}.result-count{font-size:11px;color:#9aa69f}.filter{margin-left:auto;border:1px solid #dfe8e2;background:#fff;border-radius:6px;padding:8px 12px;color:#728178;font-size:11px}table{width:100%;border-collapse:collapse;text-align:left}th{color:#9ca9a1;font-size:9px;letter-spacing:.8px;font-weight:700;padding:13px 20px;background:#fbfcfb}td{padding:15px 20px;border-top:1px solid #f0f3f1;font-size:11px;color:#68776e}td strong{color:#314139;font-size:11px}.code{font-family:monospace;color:#94a39a}.status{color:#39976a;font-size:10px}.status i{display:inline-block;background:#4eae7b;width:6px;height:6px;border-radius:50%;margin-right:4px}.more{font-size:16px;color:#a4afa8}.action-cards{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.action-cards button{background:#fff;border:1px solid #e9efeb;border-radius:10px;padding:22px;text-align:left;box-shadow:0 3px 14px #153b2408}.action-cards .quick-icon{margin-bottom:18px}.action-cards strong,.action-cards small{display:block}.action-cards strong{font-size:13px}.action-cards small{color:#99a69e;font-size:11px;margin-top:5px}.type-pill{border-radius:20px;padding:5px 9px;font-size:10px}.type-pill.purchase,.type-pill.opening{background:#e7f4eb;color:#398d63}.type-pill.sale{background:#fff0e8;color:#d17f61}.type-pill.adjustment{background:#f0edfa;color:#8371b2}.delta{font-weight:700;color:#3b956a}.modal-backdrop{position:fixed;inset:0;background:#18352645;display:grid;place-items:center;z-index:5}.modal{position:relative;background:#fff;width:390px;border-radius:12px;padding:30px;box-shadow:0 20px 60px #173d2780}.modal h2{font:800 22px Manrope;margin:0}.close{position:absolute;right:18px;top:15px;border:0;background:transparent;color:#9aa69f;font-size:22px}.modal form{margin-top:24px}.modal label{display:block;color:#66766d;font-size:11px;font-weight:700;margin-bottom:15px}.modal input,.modal select{display:block;width:100%;margin-top:7px;padding:10px;border:1px solid #dfe8e2;border-radius:6px;outline:0;color:#405047;font-size:12px;background:#fff}.modal input:focus,.modal select:focus{border-color:#54a67e}.optional{color:#aab4ae;font-weight:400;margin-left:4px}.wide{width:100%;margin-top:6px}.error{background:#fff0ec;color:#c56e57;padding:10px;border-radius:6px;font-size:11px;margin:15px 0 0}
        @media(max-width:1100px){.page{padding-left:28px;padding-right:28px}.topbar{padding:0 28px}.dashboard-grid{grid-template-columns:1fr}.sidebar{width:220px}}
      </style>
    </section>
  </main>
</div>

{#if showProductForm || showMovementForm}
  <div class="modal-backdrop" role="presentation" onclick={(event) => event.target === event.currentTarget && (showProductForm = showMovementForm = false)}>
    <div class="modal"><button class="close" onclick={() => showProductForm = showMovementForm = false}>×</button>{#if showProductForm}<p class="eyebrow">NEW PRODUCT</p><h2>Add a product</h2><p class="modal-subtitle">Start tracking an item in your inventory.</p><form onsubmit={saveProduct}><label>Product name<input required bind:value={name} placeholder="e.g. Arabica Coffee Beans" /></label><label>Unit<select bind:value={unit}><option>pieces</option><option>boxes</option><option>bags</option><option>packs</option></select></label><label>Opening stock<input type="number" min="0" bind:value={openingQuantity} /></label><button class="primary wide" disabled={isSaving}>{isSaving ? "Saving..." : "Create product"}</button></form>{:else}<p class="eyebrow">{movementType.toUpperCase()}</p><h2>Record a {movementType}</h2><p class="modal-subtitle">This creates a permanent transaction record.</p><form onsubmit={saveMovement}><label>Product<select bind:value={selectedProductId}>{#each products as product}<option value={product.id}>{product.name} · {product.currentStock} {product.unit} available</option>{/each}</select></label><label>Quantity<input required type="number" min="1" bind:value={quantity} /></label><label>Note <span class="optional">Optional</span><input bind:value={note} placeholder="What is this for?" /></label><button class="primary wide" disabled={isSaving}>{isSaving ? "Saving..." : "Save movement"}</button></form>{/if}{#if error}<p class="error">{error}</p>{/if}</div>
  </div>
{/if}
